<template>
  <v-app-bar :elevation="0">
    <div class="head-center">
      <v-app-bar-title>
        <img
            src="@/assets/images/app-logo.svg"
            alt="flitt logo"
            width="110"
            class="cursor-pointer"
            @click="goToHomepage"
        />
      </v-app-bar-title>
      <v-badge
          v-if="vxCartTotalQuantity > 0"
          :class="['px-4', { 'slide-fade-enter': isAnimate }]"
          color="red"
          :content="vxCartTotalQuantity"
          offset-x="6"
          offset-y="8"
          floating
      >
        <v-icon color="gray" size="32" class="cursor-pointer" @click="viewCart">mdi-cart-outline</v-icon>
      </v-badge>
      <v-icon v-else color="gray" size="32" class="cursor-pointer px-4" @click="viewCart">mdi-cart-outline</v-icon>
    </div>
  </v-app-bar>
</template>

<script>
// Vuex
import {createNamespacedHelpers as nameSpace} from "vuex";

const {
  mapGetters: cartGetters,
} = nameSpace("cartModule");

export default {
  name: "Header",
  data() {
    return {
      isAnimate: false,
    };
  },
  computed: {
    ...cartGetters({
      vxCartTotalQuantity: "totalQuantity",
    }),
  },
  methods: {
    viewCart() {
      this.$router.push('/cart');
    },
    goToHomepage() {
      window.location.href = '/#/'
    },
  },
  watch: {
    vxCartTotalQuantity(val) {
      if (val) {
        this.isAnimate = true;
        setTimeout(() => {
          this.isAnimate = false;
        }, 500)
      }
    },
  },
}
</script>
<style lang="scss">
.head-center {
  display: flex;
  max-width: 1200px;
  width: 100%;
  margin: auto;
  vertical-align: middle;
  align-items: center;
  padding-left: 10px;
  padding-right: 10px;
}
</style>